CREATE TABLE identity_refresh_token_history (token_hash varchar(64) PRIMARY KEY,session_id varchar(64) NOT NULL,expires_at timestamp(6) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,KEY identity_refresh_token_history_session_idx(session_id),KEY identity_refresh_token_history_expiry_idx(expires_at,token_hash),CONSTRAINT identity_refresh_token_history_session_fk FOREIGN KEY(session_id) REFERENCES identity_sessions(id),CONSTRAINT identity_refresh_token_history_hash_length CHECK(CHAR_LENGTH(token_hash)=64));
CREATE TRIGGER identity_refresh_token_history_audit_bi BEFORE INSERT ON identity_refresh_token_history FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL ELSE NULLIF(TRIM(@app_actor_id),'') END;
CREATE TRIGGER identity_refresh_token_history_audit_bu BEFORE UPDATE ON identity_refresh_token_history FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER identity_refresh_token_history_audit_bd BEFORE DELETE ON identity_refresh_token_history FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
